// française sous une interface allemande.
function ggGetCriterionTooltip(criterion, lang) {
  const phrase = (mots) => choisirMot(mots, lang);
  if (criterion.type === "club") {
    const c = criterion.value;
    return phrase({
      fr: `Le joueur a évolué au ${c} (au moins une saison professionnelle).`,
      en: `The player played at ${c} (at least one professional season).`,
      de: `Der Spieler stand bei ${c} unter Vertrag (mindestens eine Profisaison).`,
      it: `Il giocatore ha giocato al ${c} (almeno una stagione da professionista).`,
      pt: `O jogador atuou no ${c} (pelo menos uma temporada profissional).`,
      es: `El jugador jugó en el ${c} (al menos una temporada profesional).`,
    });
  }
  if (criterion.type === "nationality") {
    const p = nomPays(criterion.value, lang);
    return phrase({
      fr: `Le joueur a la nationalité sportive ${p}.`,
      en: `The player has the sporting nationality of ${p}.`,
      de: `Der Spieler besitzt die Sportnationalität ${p}.`,
      it: `Il giocatore ha la nazionalità sportiva ${p}.`,
      pt: `O jogador tem a nacionalidade esportiva ${p}.`,
      es: `El jugador tiene la nacionalidad deportiva ${p}.`,
    });
  }
  if (criterion.type === "position") {
    const p = nomPosteLong(criterion.value, lang);
    return phrase({
      fr: `Le joueur évolue principalement au poste de ${p}.`,
      en: `The player primarily plays as a ${p}.`,
      de: `Der Spieler spielt hauptsächlich als ${p}.`,
      it: `Il giocatore gioca principalmente da ${p}.`,
      pt: `O jogador atua principalmente como ${p}.`,
      es: `El jugador juega principalmente de ${p}.`,
    });
  }
  if (criterion.type === "league") {
    const l = nomLigueLongue(criterion.value, lang);
    return phrase({
      fr: `Le joueur a évolué dans au moins un club de ${l}.`,
      en: `The player has played in at least one club of the ${l}.`,
      de: `Der Spieler hat bei mindestens einem Klub der ${l} gespielt.`,
      it: `Il giocatore ha giocato in almeno un club della ${l}.`,
      pt: `O jogador atuou em pelo menos um clube da ${l}.`,
      es: `El jugador jugó en al menos un club de la ${l}.`,
    });
  }
  if (criterion.type === "trophy") {
    if (criterion.value === "world_cup") return phrase({
      fr: "Le joueur a remporté au moins une Coupe du Monde avec sa sélection nationale.",
      en: "The player has won at least one World Cup with their national team.",
      de: "Der Spieler hat mit seiner Nationalmannschaft mindestens eine Weltmeisterschaft gewonnen.",
      it: "Il giocatore ha vinto almeno un Mondiale con la sua nazionale.",
      pt: "O jogador venceu pelo menos uma Copa do Mundo com a sua seleção.",
      es: "El jugador ganó al menos un Mundial con su selección.",
    });
    if (criterion.value === "champions_league") return phrase({
      fr: "Le joueur a remporté au moins une UEFA Champions League avec son club.",
      en: "The player has won at least one UEFA Champions League with their club.",
      de: "Der Spieler hat mit seinem Klub mindestens eine UEFA Champions League gewonnen.",
      it: "Il giocatore ha vinto almeno una UEFA Champions League con il suo club.",
      pt: "O jogador venceu pelo menos uma UEFA Champions League com o seu clube.",
      es: "El jugador ganó al menos una UEFA Champions League con su club.",
    });
    return phrase({
      fr: "Le joueur a remporté ce trophée.", en: "The player has won this trophy.",
      de: "Der Spieler hat diese Trophäe gewonnen.", it: "Il giocatore ha vinto questo trofeo.",
      pt: "O jogador conquistou este troféu.", es: "El jugador ganó este trofeo.",
    });
  }
  if (criterion.type === "coach") {
    return phrase({
      fr: "Cet ancien joueur est ensuite devenu entraîneur.",
      en: "This former player later became a manager/coach.",
      de: "Dieser frühere Spieler wurde später Trainer.",
      it: "Questo ex giocatore è poi diventato allenatore.",
      pt: "Este ex-jogador tornou-se depois treinador.",
      es: "Este exjugador se convirtió después en entrenador.",
    });
  }
  return "";
}

// Libellé affiché d'un critère, dans les six langues.
//
// `criterion.label` est écrit en FRANÇAIS à la génération de la grille : c'est
// la clé, pas le texte à montrer. On ne s'en sert donc que comme dernier repli
// (un club, dont le nom ne se traduit pas).
// ── Le libellé d'une pastille de critère, AJUSTÉ À LA MESURE ───────────────
//
// Signalé : « A JOUÉ EN SÉRIE A » sortait coupé en « SE-RIE ». Le corps était FIGÉ
// à 11,5 px quelle que soit la longueur du libellé, et la pastille fait moins de
// 80 px de large : le navigateur cassait donc le mot, avec une césure là où la
// langue du document le permettait, ou en laissant un « A » seul sur la ligne
// suivante selon la largeur de l'écran. Deux symptômes, une seule cause.
//
// `hyphens:none` était nécessaire — il n'y a aucune raison de couper un mot dans
// une pastille de trois mots — mais PAS suffisant : sans césure, le mot se casse
// quand même, sans le tiret. Ce qu'il faut, c'est que le texte TIENNE.
//
// Mesuré à la largeur réelle, police du logo : « A JOUÉ EN SÉRIE A » déborde à
// 11,5 px et tient sur une ligne dès 10 px.
//
// TROIS SEUILS, la même recette que la question de GOAT GUESS, et pour la même
// raison : deux seuils forceraient un mauvais compromis. Les libellés courts
// méritent leur pleine taille ; « VAINQUEUR LIGUE DES CHAMPIONS » ne tiendra
// jamais sur une ligne et n'a pas à être puni pour autant.
const PASTILLE_MAX = 11.5;      // le confort des libellés courts
const PASTILLE_PLANCHER = 9;    // jusqu'où on descend POUR TENIR SUR UNE LIGNE
const PASTILLE_REPLI = 10.5;    // le corps quand une ligne est hors d'atteinte
function LibelleCritere(props) {
  const ref = React.useRef(null);
  const [corps, setCorps] = React.useState(PASTILLE_MAX);
  React.useLayoutEffect(function(){
    const el = ref.current;
    if (!el) return;
    let annule = false;
    function ajuster() {
      if (annule || !ref.current) return;
      const e = ref.current;
      const large = e.parentElement ? e.parentElement.clientWidth : 0;
      if (!large) return;
      let px = PASTILLE_MAX;
      e.style.fontSize = px + "px";
      // Une seule ligne = la hauteur rendue tient dans une hauteur de ligne.
      const uneLigne = function(){ return e.scrollHeight <= Math.ceil(px * 1.15) + 1; };
      while (!uneLigne() && px > PASTILLE_PLANCHER) { px -= 0.5; e.style.fontSize = px + "px"; }
      const retenu = uneLigne() ? px : PASTILLE_REPLI;
      // On REPOSE la taille explicitement. Effacer le style après mesure puis
      // appeler setCorps avec la valeur qu'il avait déjà ne re-rend pas : le style
      // effacé n'est alors jamais réécrit et tout sort au corps hérité. C'est le
      // défaut qui avait fait sortir les quatorze questions de GOAT GUESS à 16 px.
      e.style.fontSize = retenu + "px";
      setCorps(retenu);
    }
    ajuster();
    // La police du logo arrive après le premier rendu : mesurer avant elle donne
    // la largeur de la police de repli, donc un mauvais verdict.
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(ajuster).catch(function(){});
    window.addEventListener("resize", ajuster);
    return function(){ annule = true; window.removeEventListener("resize", ajuster); };
  }, [props.texte]);
  return <div ref={ref} style={{fontSize:corps+"px"}}>{props.texte}</div>;
}

function ggGetCriterionDisplayLabel(criterion, lang) {
  if (criterion.type === "position") return nomPoste(criterion.value, lang);
  if (criterion.type === "nationality") return nomPays(criterion.value, lang);
  if (criterion.type === "league") return nomLigue(criterion.value, lang);
  if (criterion.type === "trophy") return nomTrophee(criterion.value, lang);
  if (criterion.type === "coach") return choisirMot(MOT_ENTRAINEUR, lang);
  return criterion.label;
}

// ══ MULTIPLAYER ENGINE (BroadcastChannel + localStorage) ══
// Works between browser tabs. Replace with Supabase for cross-device.

const MAX_PLAYERS = 10;

function mpStore(key) { return `bb_mp_${key}`; }

function mpGetRoom(code) {
  try { const d = localStorage.getItem(mpStore(code)); return d ? JSON.parse(d) : null; } catch { return null; }
}

function mpSaveRoom(code, room) {
  try { localStorage.setItem(mpStore(code), JSON.stringify(room)); } catch {}
}

function mpDeleteRoom(code) {
  try { localStorage.removeItem(mpStore(code)); } catch {}
}

function createRoom(code, hostName, diff, gameMode, totalRounds) {
  const room = {
    code, hostName, diff, gameMode, totalRounds: totalRounds || 1,
    status: "lobby",
    seed: Math.floor(Math.random() * 9999999),
    createdAt: Date.now(),
    players: [{ id: code + "_0", name: hostName, score: 0, status: "waiting", isHost: true, joinedAt: Date.now() }],
  };
  mpSaveRoom(code, room);
  return room;
}

function joinRoom(code, playerName) {
  const room = mpGetRoom(code);
  if (!room) return { error: "Partie introuvable" };
  if (room.status !== "lobby") return { error: "Partie déjà commencée" };
  if (room.players.length >= MAX_PLAYERS) return { error: `Maximum ${MAX_PLAYERS} joueurs atteint` };
  if (room.players.find(p => p.name === playerName)) return { error: "Ce pseudo est déjà pris" };
  const player = { id: code + "_" + room.players.length, name: playerName, score: 0, status: "waiting", isHost: false, joinedAt: Date.now() };
  room.players.push(player);
  mpSaveRoom(code, room);
  return { room, player };
}

function generateCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({length:4}, ()=>chars[Math.floor(Math.random()*chars.length)]).join("");
}

function getClubColors(name){return CLUB_COLORS[name]||["#1a7a3a","#FFFFFF"];}

function ClubLogo({ club, size = 48 }) {
  const [ca, cb] = getClubColors(club);
  // Surcharges d'initiales pour les clubs italiens renommés (sinon "AR", "JF", "AB"... pas top)
  const INITIALS_OVERRIDE = {
    "AS Roma": "ASR",
    "SS Lazio": "SSL",
    "Juventus FC": "JUVE",
    "SSC Napoli": "NAP",
    "ACF Fiorentina": "FIO",
    "Atalanta BC": "ATA",
    "Bologna FC": "BOL",
    "Torino FC": "TOR",
    "Genoa CFC": "GEN",
    "Cagliari Calcio": "CAG",
    "Udinese Calcio": "UDI",
    "Empoli FC": "EMP",
    "Parma FC": "PAR",
  };
  const initials = INITIALS_OVERRIDE[club] || club.split(" ").map(w => w[0]).join("").slice(0, 3).toUpperCase();
  const fontSize = size < 36 ? (initials.length >= 4 ? size * 0.26 : size * 0.32) : (initials.length >= 4 ? size * 0.22 : size * 0.28);
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%",
      background: `linear-gradient(135deg, ${ca} 0%, ${ca}cc 100%)`,
      border: `${Math.max(1.5, size * 0.04)}px solid ${cb}44`,
      display: "flex", alignItems: "center", justifyContent: "center",
      boxShadow: `0 2px 8px rgba(0,0,0,.4), inset 0 1px 0 ${cb}33`,
      flexShrink: 0,
    }}>
      <span style={{
        fontSize, fontWeight: 900, color: cb,
        fontFamily: "Arial Black, Arial, sans-serif",
        letterSpacing: initials.length > 2 ? -1 : 0,
        textShadow: `0 1px 2px rgba(0,0,0,.5)`,
        lineHeight: 1,
      }}>{initials}</span>
    </div>
  );
}

function textColor(hex){const r=parseInt(hex.slice(1,3),16),g=parseInt(hex.slice(3,5),16),b=parseInt(hex.slice(5,7),16);return(r*299+g*587+b*114)/1000>128?"#111":"#FFF";}
function generateOptions(correctPlayers,allPairs,seed,targetDiff){
  // seed optionnel : en multi room, permet d'avoir les MÊMES 4 options chez tous les joueurs
  const rand = (seed !== undefined && seed !== null) ? seededRandom(seed) : Math.random;
  // Mode AMATEUR : une paire est classée "facile" parce qu'AU MOINS un joueur
  // facile la relie, mais un tirage uniforme parmi tous les ponts n'a en
  // moyenne qu'1 chance sur 3 de le montrer (ex : Barcelone-OM → 6 fois sur 7
  // la bonne réponse était Zenden/Dugarry/Keita au lieu d'Alexis Sanchez).
  // On restreint donc la bonne réponse affichée aux joueurs "facile" du pont
  // (repli "moyen" si aucun). Le filtre est déterministe → OK en multi seedé.
  let candidates = correctPlayers;
  if (targetDiff === "facile") {
    for (const d of ["facile", "moyen"]) {
      const subset = correctPlayers.filter(p => PLAYER_DIFF[p] === d);
      if (subset.length) { candidates = subset; break; }
    }
  }
  const correct=candidates[Math.floor(rand()*candidates.length)];
  const pool=[];allPairs.forEach(pair=>pair.p.forEach(p=>{if(!correctPlayers.includes(p))pool.push(p);}));
  // Seeded shuffle pour les distracteurs
  const poolCopy=[...new Set(pool)];
  for(let i=poolCopy.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[poolCopy[i],poolCopy[j]]=[poolCopy[j],poolCopy[i]];}
  const wrongs=poolCopy.slice(0,3);
  // Seeded shuffle pour l'ordre final
  const out=[correct,...wrongs];
  for(let i=out.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[out[i],out[j]]=[out[j],out[i]];}
  return out;
}
function getComboLabel(c){if(c>=10)return"🔥 LEGENDARY";if(c>=7)return"💫 AMAZING";if(c>=5)return"⚡ ON FIRE";if(c>=3)return"🎯 COMBO";return"";}

// ── SOUNDS ──
// Contexte audio unique (réutilisé) — éviter d'en créer un par son (limite navigateur)
let _sndCtx=null;
function sndCtx(){
  try{
    if(!_sndCtx){ const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return null; _sndCtx=new AC(); }
    if(_sndCtx.state==="suspended") _sndCtx.resume();
    return _sndCtx;
  }catch(e){ return null; }
}
function playSound(type){
  try{
    const ctx=sndCtx(); if(!ctx) return;
    if(type==="tick"){
      const osc=ctx.createOscillator(),g=ctx.createGain();
      osc.connect(g);g.connect(ctx.destination);osc.type="square";osc.frequency.value=1500;
      g.gain.setValueAtTime(.0001,ctx.currentTime);g.gain.linearRampToValueAtTime(.05,ctx.currentTime+.005);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.05);
      osc.start(ctx.currentTime);osc.stop(ctx.currentTime+.06);
      return;
    }
    if(type==="clocktick"){
      const osc=ctx.createOscillator(),g=ctx.createGain();
      osc.connect(g);g.connect(ctx.destination);osc.type="sine";osc.frequency.value=900;
      g.gain.setValueAtTime(.0001,ctx.currentTime);g.gain.linearRampToValueAtTime(.22,ctx.currentTime+.005);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.09);
      osc.start(ctx.currentTime);osc.stop(ctx.currentTime+.1);
      return;
    }
    if(type==="spinstop"){
      [880,1175,1568].forEach((freq,i)=>{
        const osc=ctx.createOscillator(),g=ctx.createGain();
        osc.connect(g);g.connect(ctx.destination);osc.frequency.value=freq;osc.type="triangle";
        g.gain.setValueAtTime(0,ctx.currentTime+i*.06);g.gain.linearRampToValueAtTime(.22,ctx.currentTime+i*.06+.01);
        g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.06+.2);
        osc.start(ctx.currentTime+i*.06);osc.stop(ctx.currentTime+i*.06+.2);
      });
      return;
    }
    if(type==="ok"){
      [523,659,784].forEach((freq,i)=>{
        const osc=ctx.createOscillator(),g=ctx.createGain();
        osc.connect(g);g.connect(ctx.destination);osc.frequency.value=freq;osc.type="sine";
        g.gain.setValueAtTime(0,ctx.currentTime+i*.1);g.gain.linearRampToValueAtTime(.3,ctx.currentTime+i*.1+.02);
        g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.1+.3);
        osc.start(ctx.currentTime+i*.1);osc.stop(ctx.currentTime+i*.1+.3);
      });
    }else if(type==="combo"){
      [659,784,988,1175].forEach((freq,i)=>{
        const osc=ctx.createOscillator(),g=ctx.createGain();
        osc.connect(g);g.connect(ctx.destination);osc.frequency.value=freq;osc.type="sine";
        g.gain.setValueAtTime(0,ctx.currentTime+i*.08);g.gain.linearRampToValueAtTime(.35,ctx.currentTime+i*.08+.02);
        g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.08+.25);
        osc.start(ctx.currentTime+i*.08);osc.stop(ctx.currentTime+i*.08+.25);
      });
    }else if(type==="milestone"){
      // Fanfare triomphale montante (palier de chaîne franchi)
      [523,659,784,1047,1319].forEach((freq,i)=>{
        const osc=ctx.createOscillator(),g=ctx.createGain();
        osc.connect(g);g.connect(ctx.destination);osc.frequency.value=freq;osc.type="triangle";
        g.gain.setValueAtTime(0,ctx.currentTime+i*.09);g.gain.linearRampToValueAtTime(.4,ctx.currentTime+i*.09+.02);
        g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.09+.45);
        osc.start(ctx.currentTime+i*.09);osc.stop(ctx.currentTime+i*.09+.45);
      });
    }else{
      const osc=ctx.createOscillator(),g=ctx.createGain();
      osc.connect(g);g.connect(ctx.destination);osc.frequency.setValueAtTime(220,ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(110,ctx.currentTime+.3);osc.type="sawtooth";
      g.gain.setValueAtTime(.3,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.3);
      osc.start(ctx.currentTime);osc.stop(ctx.currentTime+.3);
    }
  }catch(e){}
}

// Vibration haptique mobile — ne fait rien si non supporté (desktop/iOS Safari)
function vibrate(pattern){
  try{ if(navigator.vibrate) navigator.vibrate(pattern); }catch(e){}
}

